package httpapi

import "html/template"

var surveyTemplateV2 = template.Must(template.New("survey-v2").Parse(`<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Перед первым костром</title><style>
:root{color-scheme:dark;--bg:#070b14;--panel:#111827e8;--line:#c99b5540;--gold:#e5b75f;--violet:#b76cff;--text:#f4ecdf;--muted:#9aa2b2;font-family:Inter,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--text);background:radial-gradient(circle at 78% 9%,#54237544,transparent 27%),radial-gradient(circle at 15% 88%,#7c4b182c,transparent 25%),linear-gradient(#050914e8,#09101cee),repeating-radial-gradient(circle at 50% 20%,transparent 0 44px,#d2a45b0b 45px 46px);overflow-x:hidden}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.24;background-image:linear-gradient(115deg,transparent 47%,#e7b55b22 49%,transparent 51%),radial-gradient(circle,#fff 0 1px,transparent 1.5px);background-size:600px 600px,73px 73px}.page{width:min(1180px,92vw);margin:auto;padding:32px 0 70px}.top{display:grid;grid-template-columns:1.45fr .72fr;gap:50px;align-items:start}.progress{display:flex;align-items:center;gap:14px;color:#aaa;font-size:14px}.sigil,.ico{display:grid;place-items:center;border:1px solid #d3a34f66;background:#101623;border-radius:14px;color:var(--gold);box-shadow:0 0 25px #c78a3530}.sigil{width:46px;height:46px;border-radius:50%;font-size:22px}.bar{height:6px;width:260px;background:#2c3243;border-radius:9px;overflow:hidden}.bar i{display:block;width:34%;height:100%;background:linear-gradient(90deg,var(--gold),#f6d592)}h1{font:700 clamp(48px,7vw,82px)/.97 Georgia,serif;letter-spacing:-2px;margin:28px 0 14px;max-width:670px}.diamond{color:var(--violet);font-size:.45em}.lead{font-size:18px;line-height:1.6;color:#b9bdc7;max-width:650px}.privacy{display:flex;gap:10px;color:#969eab;margin:30px 0}.music-panel{padding-top:0}.music-toggle{width:100%;height:68px;border:1px solid #dd8aff;border-radius:14px;background:linear-gradient(110deg,#34104fdd,#27152cdc);color:#fff;font-weight:700;font-size:17px;box-shadow:0 0 35px #b74dff55;cursor:pointer}.track{margin-top:28px;padding:18px;border:1px solid #ffffff26;border-radius:16px;background:#111722dd;display:grid;grid-template-columns:72px 1fr;gap:16px}.cover{border-radius:12px;background:radial-gradient(circle at 70% 30%,#b758ff88,transparent 25%),linear-gradient(135deg,#1d1938,#0a1322);min-height:72px}.track b{display:block;margin:4px 0}.track small{color:var(--muted)}.controls{display:flex;gap:12px;align-items:center;margin-top:14px}.round{width:38px;height:38px;border-radius:50%;border:1px solid var(--gold);background:#141b28;color:#fff}.volume{height:5px;flex:1;background:linear-gradient(90deg,var(--gold) 72%,#3d3656 72%);border-radius:8px}.sheet{margin-top:30px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,#101826f2,#0c1320f2);box-shadow:0 28px 90px #0008;padding:12px 34px 28px}.row{display:grid;grid-template-columns:78px 1fr;gap:18px;padding:22px 0;border-bottom:1px solid #ffffff0b}.row:last-of-type{border-bottom:0}.step{display:flex;align-items:flex-start;gap:12px;color:var(--gold);font:700 20px Georgia}.ico{width:52px;height:52px;font:24px Georgia}.field h2{font:600 21px Georgia;margin:8px 0 12px}.sub{font:400 13px Inter;color:var(--muted);margin-left:8px}input,textarea{width:100%;border:1px solid #ffffff24;background:#09111fd0;color:var(--text);border-radius:10px;padding:14px 16px;font:inherit;outline:0;transition:.2s}input:focus,textarea:focus{border-color:#a963db;box-shadow:0 0 0 3px #a963db22}textarea{min-height:72px;resize:vertical}.hint{font-size:13px;color:#818a99;margin:7px 0}.character-box{margin-top:12px;padding:16px;border:1px solid #db9a4f44;border-radius:12px;background:linear-gradient(120deg,#111a28,#25182855)}.character-box h3{font:500 18px Georgia;margin:0 0 12px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.choices{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.choice{position:relative}.choice input{position:absolute;opacity:0}.choice span{display:flex;align-items:center;min-height:56px;padding:10px 13px;border:1px solid #ffffff21;border-radius:9px;background:#0b1320;color:#aeb4c0;font-size:13px;cursor:pointer;transition:.2s}.choice input:checked+span{color:#f5e9ff;border-color:#bd6cff;background:linear-gradient(115deg,#50216ca8,#2a193c);box-shadow:0 0 18px #a64de83d}.submit{width:100%;height:70px;border:1px solid #f5bf79;border-radius:12px;background:linear-gradient(105deg,#542195,#7a2d90 52%,#d6874d);color:#ffe9d0;font:700 25px Georgia;box-shadow:0 0 30px #b85cff55;cursor:pointer}.status{text-align:center;color:#d8b7ef}.saved{text-align:center;color:#7f8795;font-size:13px}.trap{position:absolute;left:-9999px}@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}.top,.sheet{animation:rise .7s ease both}.sheet{animation-delay:.12s}
@media(max-width:800px){.page{width:min(100%,620px);padding:14px 12px 40px}.top{grid-template-columns:1fr;gap:4px;padding:0 8px}.progress{gap:8px;font-size:12px;white-space:nowrap}.sigil{width:38px;height:38px;font-size:18px}.bar{width:auto;min-width:72px;flex:1}h1{font-size:clamp(42px,12vw,56px);letter-spacing:-1px;margin:20px 0 10px}.lead{font-size:15px;line-height:1.5;margin:0}.privacy{font-size:13px;margin:18px 0}.music-panel{margin:6px 0 16px}.music-toggle{height:54px;font-size:15px}.track{display:none}.sheet{margin-top:0;padding:4px 14px 18px;border-radius:15px}.row{grid-template-columns:48px minmax(0,1fr);gap:10px;padding:16px 0}.step{display:block}.step>span:last-child{display:none}.ico{width:42px;height:42px;border-radius:11px;font-size:20px}.field h2{font-size:18px;line-height:1.2;margin:5px 0 10px}.sub{display:block;margin:5px 0 0;font-size:11px;font-family:Inter,sans-serif}input,textarea{padding:12px 13px;font-size:14px}textarea{min-height:68px}.hint{font-size:11px;line-height:1.35;margin:6px 0}.character-box{padding:12px;margin-top:9px}.character-box h3{font-size:16px}.grid2{grid-template-columns:1fr;gap:8px}.choices{grid-template-columns:1fr 1fr;gap:8px}.choice span{min-height:46px;padding:8px 10px;font-size:12px;line-height:1.25}.submit{height:58px;font-size:21px;margin-top:8px}.saved{font-size:11px;margin-bottom:4px}}
@media(max-width:370px){.page{padding-left:7px;padding-right:7px}.top{padding:0 5px}.sheet{padding-left:10px;padding-right:10px}.row{grid-template-columns:42px minmax(0,1fr);gap:8px}.ico{width:38px;height:38px}.choices{grid-template-columns:1fr}.progress>span:nth-child(3),.progress>span:nth-child(4){display:none}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style></head><body><div id="yt" hidden></div><main class="page"><header class="top"><section><div class="progress"><span class="sigil">☼</span><b>Шаг 1 из 3</b><span>•</span><span>Знакомство</span><span class="bar"><i></i></span></div><h1>Перед первым<br>костром <span class="diamond">◆</span></h1><p class="lead">Эта анкета поможет мастеру собрать ожидания игроков и создать кампанию, которая запомнится.</p><p class="privacy">▣ <span>Ответы видит только мастер и хранятся в безопасности.</span></p></section><aside class="music-panel"><button class="music-toggle" id="music" type="button">♫ &nbsp; Включить атмосферу</button><div class="track"><span class="cover"></span><div><b>Тихая ночь в средневековой деревне</b><small>YouTube • фэнтези-эмбиент</small><div class="controls"><button class="round" id="pause" type="button">▶</button><span>♬</span><span class="volume"></span></div></div></div></aside></header>
<form class="sheet" id="f"><div class="trap"><label>Website <input name="website" autocomplete="off"></label></div>
<section class="row"><div class="step"><span class="ico">♙</span><span>1</span></div><div class="field"><h2>Как к вам обращаться?</h2><input name="name" required maxlength="120" placeholder="Имя или псевдоним"></div></section>
<section class="row"><div class="step"><span class="ico">◫</span><span>2</span></div><div class="field"><h2>Желаемый мир / сеттинг</h2><textarea name="setting" maxlength="2000" placeholder="Опишите мир, эпоху, технологии, магию, настроение..."></textarea><p class="hint">Например: тёмное фэнтези, стимпанк, античность, постапокалипсис.</p></div></section>
<section class="row"><div class="step"><span class="ico">⚔</span><span>3</span></div><div class="field"><h2>Опыт в НРИ и комфорт с правилами</h2><textarea name="inspirations" maxlength="2000" placeholder="Играли ли вы раньше? Насколько вам комфортны правила, броски, тактика и отыгрыш?"></textarea><p class="hint">Это поможет мастеру понять, сколько объяснений и поддержки нужно на старте.</p></div></section>
<section class="row"><div class="step"><span class="ico">♜</span><span>4</span></div><div class="field"><h2>Персонаж или роль, которую хочется попробовать</h2><input name="character" maxlength="2000" placeholder="Кем вы видите своего героя? Какую роль хотели бы отыгрывать?"><div class="character-box"><h3>Детали персонажа <span class="sub">— все поля необязательные</span></h3><div class="grid2"><input name="characterName" placeholder="Имя персонажа"><input name="characterClass" placeholder="Предварительный класс"><input name="ancestry" placeholder="Раса / происхождение"><input name="partyRole" placeholder="Роль в группе"></div><textarea name="backstory" placeholder="Короткая предыстория" style="margin-top:10px"></textarea></div></div></section>
<section class="row"><div class="step"><span class="ico">✦</span><span>5</span></div><div class="field"><h2>Тон кампании <span class="sub">• Можно выбрать несколько вариантов</span></h2><div class="choices" data-group="tone">{{range .Tones}}<label class="choice"><input type="checkbox" value="{{.}}"><span>{{.}}</span></label>{{end}}</div></div></section>
<section class="row"><div class="step"><span class="ico">⚔</span><span>6</span></div><div class="field"><h2>Что особенно хочется увидеть?</h2><textarea name="expectations" maxlength="2000" placeholder="Сражения, путешествия, древние тайны, развитие персонажей..."></textarea><p class="hint">Опишите ключевые моменты, которых ждёте от кампании.</p></div></section>
<section class="row"><div class="step"><span class="ico">♢</span><span>7</span></div><div class="field"><h2>Темы и границы, которых стоит избегать</h2><textarea name="boundaries" maxlength="2000" placeholder="Есть ли темы, которых вам бы не хотелось в игре?"></textarea><p class="hint">Мы уважаем границы и делаем игру комфортной для всех.</p></div></section>
<section class="row"><div class="step"><span class="ico">♫</span><span>8</span></div><div class="field"><h2>Предпочтения по атмосфере <span class="sub">• Можно выбрать несколько</span></h2><div class="choices" data-group="atmosphere">{{range .Atmospheres}}<label class="choice"><input type="checkbox" value="{{.}}"><span>{{.}}</span></label>{{end}}</div></div></section>
<button class="submit" type="submit">Отправить мастеру &nbsp; ✦</button><p class="saved">Сохранение черновика включено автоматически</p><p class="status" id="status" aria-live="polite"></p></form></main>
<script>const t={{printf "%q" .Token}},prefix='shadow-edge:survey-draft:',k=prefix+t,f=document.querySelector('#f'),s=document.querySelector('#status');const selected=g=>[...document.querySelectorAll('[data-group="'+g+'"] input:checked')].map(x=>x.value).join(', ');const data=()=>{let d=Object.fromEntries(new FormData(f));d.tone=selected('tone');d.atmosphere=selected('atmosphere');return d};try{let raw=localStorage.getItem(k);if(!raw){for(let i=0;i<localStorage.length;i++){let old=localStorage.key(i);if(old&&old.startsWith(prefix)&&localStorage.getItem(old)){raw=localStorage.getItem(old);break}}}let d=JSON.parse(raw||'{}');for(let n in d){let e=f.elements.namedItem(n);if(e)e.value=d[n]}for(let g of ['tone','atmosphere']){let vals=(d[g]||'').split(', ');document.querySelectorAll('[data-group="'+g+'"] input').forEach(x=>x.checked=vals.includes(x.value))}}catch{}f.oninput=()=>{try{localStorage.setItem(k,JSON.stringify(data()))}catch{}};let playing=false;const mb=document.querySelector('#music'),pb=document.querySelector('#pause'),yt=document.querySelector('#yt');function stop(){yt.replaceChildren();playing=false;mb.textContent='♫   Включить атмосферу';pb.textContent='▶'}function play(){const frame=document.createElement('iframe');frame.title='Фоновая музыка';frame.src='https://www.youtube-nocookie.com/embed/dJ5VtIE3kwU?autoplay=1&loop=1&playlist=dJ5VtIE3kwU&controls=0';frame.allow='autoplay; encrypted-media';frame.referrerPolicy='strict-origin-when-cross-origin';frame.style.cssText='position:fixed;width:1px;height:1px;opacity:0;pointer-events:none';yt.hidden=false;yt.replaceChildren(frame);playing=true;mb.textContent='♫   Атмосфера включена';pb.textContent='Ⅱ'}mb.onclick=()=>playing?stop():play();pb.onclick=()=>playing?stop():play();f.onsubmit=async e=>{e.preventDefault();let b=f.querySelector('[type=submit]');b.disabled=true;try{let r=await fetch('/api/survey/'+encodeURIComponent(t),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data())}),j=await r.json();if(!r.ok)throw Error(j.error?.message);for(let i=localStorage.length-1;i>=0;i--){let old=localStorage.key(i);if(old&&old.startsWith(prefix))localStorage.removeItem(old)}f.innerHTML='<div style="padding:70px 20px;text-align:center"><h2 style="font:38px Georgia">Спасибо. Мастер получил вашу весть.</h2><p>До встречи у первого костра.</p></div>'}catch(x){s.textContent=x.message||'Не удалось отправить.';b.disabled=false}};</script></body></html>`))

func surveyPageData(token string) map[string]any {
	return map[string]any{
		"Token":       token,
		"Tones":       []string{"Героическое приключение", "Тёмное фэнтези", "Политические интриги", "Исследование и тайны", "Хоррор", "Выживание", "Эпическое фэнтези", "Юмор и лёгкость", "Моральные дилеммы", "Путешествия и открытия"},
		"Atmospheres": []string{"Музыка", "Свечи", "Игровой вайб", "Загадки", "Драма", "Юмор", "Эпичность", "Спокойствие"},
	}
}
